package Java;

public class Day_2 {

	
		// TODO Auto-generated method stub
		private String name;
		private float weight;
		private int age;
		
		public String getName() {
			return name;
		}
		public Day_2(String name, float weight, int age) {
			super();
			this.name = name;
			this.weight = weight;
			this.age = age;
		}
		public void setName(String name) {
			this.name = name;
		}
		public float getWeight() {
			return weight;
		}
		public void setWeight(float weight) {
			this.weight = weight;
		}
		public int getAge() {
			return age;
		}
		public void setAge(int age) {
			this.age = age;
		}
		

	
}
